{
  "requirement_id": "SFMC-REQ-034",
  "raw_text": "The SFMC shall be capable of automatically flying the spacecraft to a safe location during an emergency.",
  "software_requirement_status": "YES",
  "quality_status": "NEEDS_REVIEW",
  "quality_issues": [
    {
      "issue_code": "UNDEFINED_TERM",
      "severity": "MAJOR",
      "explanation": "The term 'safe location' used in the requirement is undefined in the SRS. The Open Items section (#11) lists 'Definition of a safe location during an emergency' as unresolved, which creates ambiguity in the requirement's meaning and verification.",
      "srs_evidence": [
        {
          "locator": "11. Open Items",
          "excerpt": "5. Definition of a safe location during an emergency."
        }
      ],
      "nasa_references": [
        {
          "document": "NASA-HDBK-2203-5.09",
          "authority": "HANDBOOK_GUIDANCE",
          "section": "§3.2.1.4",
          "swe_id": null,
          "url": "https://swehb.nasa.gov/spaces/SWEHBVD/pages/102695669/5.09+-+SRS+-+Software+Requirements+Specification"
        }
      ],
      "recommendation": "Define 'safe location' explicitly in the SRS to remove ambiguity and enable verification of the requirement.",
      "requires_stakeholder_input": true
    },
    {
      "issue_code": "ALLOCATION_UNCLEAR",
      "severity": "MINOR",
      "explanation": "The requirement states that the SFMC shall be capable of automatic flight to a safe location during an emergency but does not specify the software functions or interfaces involved in this capability. The SRS does not explicitly allocate this function to specific software components or describe the interaction with Navigation or Propulsion subsystems for emergency automatic flight.",
      "srs_evidence": [
        {
          "locator": "3.1 Navigation",
          "excerpt": "SFMC-REQ-005 — Autopilot: When Autopilot mode is enabled, the SFMC shall control the spacecraft propulsion system to follow the selected route."
        },
        {
          "locator": "4. Emergency Operation",
          "excerpt": "SFMC-REQ-034 — Emergency Autopilot: The SFMC shall be capable of automatically flying the spacecraft to a safe location during an emergency."
        }
      ],
      "nasa_references": [
        {
          "document": "NASA-HDBK-2203-5.09",
          "authority": "HANDBOOK_GUIDANCE",
          "section": "§3.2.1.4",
          "swe_id": null,
          "url": "https://swehb.nasa.gov/spaces/SWEHBVD/pages/102695669/5.09+-+SRS+-+Software+Requirements+Specification"
        }
      ],
      "recommendation": "Clarify software allocation by specifying which software modules or interfaces are responsible for implementing the emergency automatic flight capability, including interaction with Navigation and Propulsion systems.",
      "requires_stakeholder_input": false
    }
  ],
  "primary_swe_id": null,
  "primary_swe_strength": null,
  "swe_links": [],
  "summary": "The requirement SFMC-REQ-034 mandates automatic flight to a safe location during emergencies. It is a valid software requirement but contains an undefined key term 'safe location' and lacks clear software allocation details. These issues reduce clarity and verifiability. Addressing the undefined term and clarifying software allocation will improve requirement quality."
}
